// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seed, address caller) public {
        // Keep the derived owner-address domain WIDE but ensure the zero address
        // (the bug-triggering input) is reachable by the fuzzer.
        seed = bound(seed, 0, 1000);
        address _owner = address(uint160(seed));

        // Only the current owner may call; other callers revert in both versions.
        vm.assume(caller == c.owner());

        vm.prank(caller);
        bool ok = true;
        bool s = false;
        try c.setOwner(_owner) returns (bool ret) {
            ok = true;
            s = ret;
        } catch {
            ok = false;
        }

        // General rule: whenever the call completes, it reports success (true)
        // for EVERY argument, including the zero address.
        assertTrue(ok && s);
    }
}
